from playwright.sync_api import sync_playwright
B = "http://localhost:3100"
def say(*a): print(*a, flush=True)
def login(pg, role):
    pg.goto(B + "/login"); pg.check(f"input[value={role}]"); pg.fill("input[name=password]", "localtestpw")
    pg.click("button.btn-primary"); pg.wait_for_url(B + "/")
with sync_playwright() as p:
    br = p.chromium.launch()
    ctx = br.new_context(viewport={"width": 1440, "height": 900}); ctx.set_default_timeout(10000); pg = ctx.new_page()
    errs = []; pg.on("pageerror", lambda e: errs.append(str(e)))
    login(pg, "ADMIN"); pg.screenshot(path="/tmp/d1_dispatch.png")
    say("tabs:", pg.inner_text(".tabs").replace("\n", " "))
    pg.goto(B + "/orders/DEMO-1011?tab=packing")
    pg.select_option("select[name=box]", "22x12x7_cm"); pg.fill("input[name=weight]", "560"); pg.check("input[name=stock]")
    pg.click("text=Save packing"); pg.wait_for_selector(".msg"); say("save:", pg.inner_text(".msg"))
    pg.goto(B + "/orders/DEMO-1011?tab=allocation"); say("1011 ladder:", pg.inner_text(".ladder").replace("\n", " | "))
    pg.screenshot(path="/tmp/d2_alloc.png", full_page=True)
    pg.goto(B + "/orders/DEMO-1011?tab=booking"); pg.click("text=Approve this shipment"); pg.wait_for_selector("text=Book shipment (demo)")
    pg.select_option("select[name=behavior]", "TIMEOUT_BUT_BOOKED"); pg.click("text=Book shipment (demo)"); pg.wait_for_selector(".msg"); say("timeout:", pg.inner_text(".msg"))
    pg.reload(); pg.click("text=Check courier, then book (demo)"); pg.wait_for_selector(".done"); say("book2:", pg.inner_text(".done"))
    pg.reload(); pg.screenshot(path="/tmp/d3_booking.png", full_page=True)
    pg.goto(B + "/orders/DEMO-1011?tab=packing"); pg.click("text=Print existing label"); pg.wait_for_selector(".msg"); say("print:", pg.inner_text(".msg"))
    pg.reload(); pg.click("text=Mark parcel scanned"); pg.wait_for_selector("text=Parcel scanned"); say("scan: ok")
    pg.goto(B + "/manifest"); pg.screenshot(path="/tmp/d4_manifest.png", full_page=True)
    pg.fill("input[name=count]", "1"); pg.click("button:has-text(\"Record handover\")"); pg.wait_for_selector(".msg"); say("handover wrong count:", pg.inner_text(".msg")); pg.fill("input[name=count]", "2"); pg.click("button:has-text(\"Record handover\")"); pg.wait_for_selector("text=Handed over"); say("handover ok")
    pg.goto(B + "/?stage=NEW_CASE"); pg.check("input[aria-label='Select DEMO-1001']"); pg.check("input[aria-label='Select DEMO-1004']")
    pg.click("button:has-text('Rerun recommendation')"); pg.wait_for_selector(".resultbox"); say("bulk:", pg.inner_text(".resultbox").replace("\n", " | "))
    pg.screenshot(path="/tmp/d5_bulk.png")
    for path, name in [("/tracking", "d6_tracking"), ("/ndr?tab=active&case=ndr-0994", "d7_ndr"),
                       ("/rules?p=fwd-560064-bd-surface-only&sim=1&pay=COD&intent=EXPRESS&pin=560064&w=550", "d8_rules"),
                       ("/reports", "d9_reports"), ("/settings", "d10_settings"), ("/orders/DEMO-0994?tab=tracking", "d11_track_detail")]:
        pg.goto(B + path); pg.screenshot(path=f"/tmp/{name}.png", full_page=True)
    say("stage counts after handover:", pg.goto(B + "/") and pg.inner_text(".tabs").replace("\n", " "))
    pg.goto(B + "/ndr?tab=active&case=ndr-0994"); pg.fill("textarea[name=text]", "call after 6pm"); pg.click("text=Save remark"); pg.wait_for_selector(".drawer .msg"); say("remark:", pg.inner_text(".drawer .msg"))
    pg.click("text=Request reattempt"); pg.click("text=Send (simulated)"); pg.wait_for_selector(".actbox .msg"); say("no-confirm:", pg.inner_text(".actbox .msg"))
    pg.check(".actbox[open] input[name=confirm]"); pg.click("text=Send (simulated)"); pg.wait_for_function("document.querySelector('.actbox .msg') && document.querySelector('.actbox .msg').innerText.includes('Simulated')"); say("confirmed:", pg.inner_text(".actbox .msg"))
    say("admin export:", pg.request.get(B + "/api/export?stage=NEW_CASE").text().splitlines()[0])
    ctx.clear_cookies(); login(pg, "PACKER")
    say("packer export:", pg.request.get(B + "/api/export?stage=NEW_CASE").text().splitlines()[0])
    pg.goto(B + "/orders/DEMO-1001?tab=booking"); say("packer booking blocked text:", "Only an admin" in pg.inner_text(".page"))
    pg.goto(B + "/ndr?tab=active&case=ndr-0994"); say("packer ndr reattempt reason:", pg.locator(".actbox").first.inner_text().replace("\n", " | "))
    say("anon export:", pg.context.request.get(B + "/api/export", headers={"cookie": ""}).status)
    say("js errors:", errs)
    m = br.new_context(viewport={"width": 390, "height": 844}, is_mobile=True, has_touch=True); m.set_default_timeout(10000); mp = m.new_page(); login(mp, "PACKER")
    mp.screenshot(path="/tmp/m1_dispatch.png", full_page=True)
    mp.click("button[aria-label='Open menu']"); mp.wait_for_timeout(400); mp.screenshot(path="/tmp/m2_drawer.png")
    m2 = br.new_context(viewport={"width": 360, "height": 780}, is_mobile=True, has_touch=True); m2.set_default_timeout(10000); mp2 = m2.new_page(); login(mp2, "PACKER")
    mp2.goto(B + "/orders/DEMO-1001?tab=packing"); mp2.screenshot(path="/tmp/m3_packing360.png", full_page=True)
    say("360 scrollWidth:", mp2.evaluate("document.documentElement.scrollWidth"))
    mp2.goto(B + "/ndr?tab=active&case=ndr-0999"); mp2.screenshot(path="/tmp/m4_ndr360.png", full_page=True)
    say("360 ndr scrollWidth:", mp2.evaluate("document.documentElement.scrollWidth"))
    br.close()
